using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Collections.Generic;
public static class ModelRepairWorkerProof {
 static string live;
 public static int Main(string[] args){live=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=delegate(object s,ResolveEventArgs e){return e.Name.StartsWith("Celesphonia Portable Switcher,")?Assembly.LoadFrom(live):null;};Assembly.LoadFrom(live);return Run(args);}
 static int Run(string[] args){string id=null;try{typeof(Store).GetField("Home").SetValue(null,Path.GetFullPath(args[2]));var original=LocalTranslation.Run("af2b45bbd7ba4a87ac45e54ed8cedac9");string originalJournal=LocalTranslation.RunFile(original.Id,"results.jsonl"),originalHash=Store.Hash(originalJournal);var covered=EnglishSupport.CoveredLocalSources(original.Root);var samples=new List<string>();foreach(string s in new[]{"物品","%1的%2 上升到了%3！","\\I[2518]\\c[27]媚药侵染(超敏感)"})if(covered.ContainsKey(s))samples.Add(s);
  foreach(var s in covered.Keys.Where(x=>x.Contains("ウィンドウの1行")||x=="呀…………！\r"||x=="\\i[906]\\c[4]Celesphonia : 呀…………！\r").Take(4))samples.Add(s);if(!samples.Any(x=>x.EndsWith("\r"))){string s=covered.Keys.First(x=>x.EndsWith("\r")&&x.TrimEnd('\r','\n').Length<8);samples.Add(s);}samples=samples.Distinct().Take(7).ToList();
  var run=new LocalRun{Id=Guid.NewGuid().ToString("N"),Root=original.Root,GameKey=original.GameKey,Family=original.Family,OriginVersion=original.OriginVersion,Owner=Store.Home,Name="Model repair bounded fixture",Model=original.Model,ModelHash=original.ModelHash,Language="fr",Scope=new[]{"Interface"},State="Ready"};id=run.Id;LocalTranslation.Save(run);var opts=LocalTranslation.Options(original);opts.Scope=run.Scope;opts.IncludeSources=samples.ToArray();opts.IncludeKeys=samples.Select(x=>LocalLibrary.Key(covered[x],x)).ToArray();opts.RegenerateGeneration=1;opts.RegenerateKeys=opts.IncludeKeys;opts.PackIds=new string[0];LocalTranslation.SetOptions(id,opts);LocalTranslation.Write(LocalTranslation.RunFile(id,"control.json"),new{action="run"});typeof(LocalTranslationWorker).GetMethod("Execute",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{run});run=LocalTranslation.Run(id);var results=LocalTranslation.Results(id);var failures=LocalTranslation.Read<Dictionary<string,string>>(LocalTranslation.RunFile(id,"failures.json"));
  var rows=samples.Select(s=>new{source=s,target=results.Values.Where(x=>x.Source==s).Select(x=>x.Target).FirstOrDefault(),error=failures.ContainsKey(LocalLibrary.Key(covered[s],s))?failures[LocalLibrary.Key(covered[s],s)]:null}).ToArray();bool pass=rows.All(x=>x.target!=null&&LocalLibrary.Valid(x.source,x.target))&&Store.Hash(originalJournal)==originalHash&&run.State=="Paused"&&run.LastRegenerateGeneration==1;
  string proof=Path.GetFullPath(args[1]);Directory.CreateDirectory(proof);File.Copy(LocalTranslation.RunFile(id,"results.jsonl"),Path.Combine(proof,"worker-results.jsonl"),true);LocalTranslation.Write(Path.Combine(proof,"worker.json"),new{status=pass?"PASS":"FAIL",rows,run.State,run.Done,run.Total,run.Failed,originalJournalUnchanged=Store.Hash(originalJournal)==originalHash,selectedOnly=true,temporaryRun=id});LocalTranslation.Delete(id);id=null;if(!pass)throw new Exception("Bounded worker test failed; inspect worker.json");Console.WriteLine("PASS: "+rows.Length+" real covered sources through worker; original successful journal unchanged");return 0;
 }catch(Exception e){if(id!=null)LocalTranslation.Control(id,"pause");Console.Error.WriteLine(e);return 1;}}
}
